
import { GlobalDataProps } from "@/store";
import {
  computed,
  defineComponent,
  nextTick,
  onMounted,
  onUnmounted,
  ref,
} from "vue";
import { useStore } from "vuex";
import LText from "../components/LText.vue";
import LImage from "../components/LImage.vue";
import EditWrapper from "../components/EditorWrapper.vue";
import ComponentsList from "../components/ComponentsList.vue";
// import PropsTable from "../components/PropsTable.vue";
import defaultTextTemplates from "../defaultTemplates";
import { ComponentData } from "@/store/editor";
import ImageProcesser from "@/components/ImageProcesser.vue";
import LayerList from "@/components/LayerList.vue";
import EditGroup from "@/components/EditGroup.vue";
import PropsTable from "@/components/PropsTable.vue";
import { cloneDeep, forEach, pickBy } from "lodash-es";
import initHotKeys from "@/plugins/hotKeys";
import HistoryArea from "@/components/HistoryArea.vue";
import initContextMenu from "@/plugins/contextMenu";
import { onBeforeRouteLeave, useRoute } from "vue-router";
import InputEdit from "@/components/InputEdit.vue";
import UserProfile from "@/components/UserProfile.vue";
import { Modal } from "ant-design-vue";
import html2canvas from "html2canvas";
import {
  UploadImgProps,
  imageDimensions,
  takeScreenShotAndUpload,
} from "@/helper";
import PublishForm from "./PublishForm.vue";
import PreviewForm from "./PreviewForm.vue";
import LShape from "@/components/LShape.vue";
export default defineComponent({
  components: {
    LText,
    LImage,
    ImageProcesser,
    ComponentsList,
    EditWrapper,
    // PropsTable,
    LayerList,
    EditGroup,
    PropsTable,
    HistoryArea,
    InputEdit,
    UserProfile,
    PublishForm,
    PreviewForm,
    LShape,
  },
  setup() {
    /** 两个插件 */
    initHotKeys();
    initContextMenu();
    const route = useRoute();
    const currentWorkId = route.params.id;

    const store = useStore<GlobalDataProps>();
    const components = computed(() => store.state.editor.components);
    const page = computed(() => store.state.editor.page);
    const userInfo = computed(() => store.state.user);
    const isDirty = computed(() => store.state.editor.isDirty);
    const channels = computed(() => store.state.editor.channels);
    const canvasFix = ref(false);
    const isPublishing = ref(false);
    const showpreview = ref(false);
    console.log("components", components);
    const showPublishForm = ref(false);
    const currentElement = computed<ComponentData | null>(
      () => store.getters.getCurrentElement
    );
    const saveIsLoading = computed(() => store.getters.isOpLoading("saveWork"));
    const pageChange = (e: any) => {
      console.log("e", e);
      store.commit("updatePage", e);
    };
    const activePanel = ref("components");
    const addItem = (data: any) => {
      console.log("data", data);
      store.commit("addComponent", cloneDeep(data));
    };
    const setActive = (id: string) => {
      store.commit("setActive", id);
    };
    const handleChange = (e: any) => {
      console.log("e3", e);

      store.commit("updateComponent", e);
    };
    const saveWork = () => {
      const { title, props, coverImg, desc, setting } = page.value;
      const payload = {
        title,
        coverImg,
        content: {
          components: components.value,
          setting,
          props,
        },
        desc,
      };
      store.dispatch("saveWork", {
        data: payload,
        urlParams: { id: currentWorkId },
      });
    };
    const updatePosition = (data: {
      left: number;
      top: number;
      id: string;
    }) => {
      const { id } = data;
      const updateData = pickBy(data, (v, k) => k !== "id");
      const keysArr = Object.keys(updateData);
      const valuesArr = Object.values(updateData).map((v) => v + "px");
      store.commit("updateComponent", { key: keysArr, value: valuesArr, id });
    };
    let timer;
    onMounted(() => {
      if (currentWorkId) {
        store.dispatch("fetchWork", { urlParams: { id: currentWorkId } });
      }
      timer = setInterval(() => {
        if (isDirty.value) {
          saveWork();
        }
      }, 5000);
    });
    onUnmounted(() => {
      clearInterval(timer);
    });
    const titleChange = (title: string) => {
      store.commit("updatePage", { key: "title", value: title, isRoot: true });
    };
    onBeforeRouteLeave((to, from, next) => {
      if (isDirty.value) {
        Modal.confirm({
          title: "作品还未保存,是否保存",
          okText: "保存",
          cancelText: "取消",
          okType: "primary",
          onOk: async () => {
            await saveWork();
            next();
          },
          onCancel: () => {
            next();
          },
        });
      } else {
        next();
      }
    });
    const publish = async () => {
      store.commit("setActive", "");
      canvasFix.value = true;
      isPublishing.value = true;
      await nextTick();
      const el = document.getElementById("canvas-area") as HTMLElement;
      try {
        const resp = await takeScreenShotAndUpload(el);

        if (resp) {
          store.commit("updatePage", {
            key: "coverImg",
            value: resp.data.data.urls[0],
            isRoot: true,
          });
          await saveWork();
          await store.dispatch("publishWork", {
            urlParams: { id: currentWorkId },
          });
          await store.dispatch("fetchChannels", {
            urlParams: { id: currentWorkId },
          });
          if (channels.value.length === 0) {
            await store.dispatch("createChannel", {
              data: { workId: parseInt(currentWorkId as string), name: "默认" },
            });
          }
          showPublishForm.value = true;
        }
      } catch (err) {
        console.log("err", err);
      } finally {
        canvasFix.value = false;
        isPublishing.value = false;
      }
    };
    const preview = async () => {
      await saveWork();
      showpreview.value = true;
    };

    const adjustHeightOnUpload = (event: {
      data: UploadImgProps;
      key: string;
    }) => {
      // check the key is background and data is correct
      console.log("event", event);
      if (event.key === "backgroundImage") {
        imageDimensions(event.data.file).then((dimension) => {
          const maxWidth = 375;
          const rate = dimension.height / dimension.width;
          if (rate > 1) {
            store.commit("updatePage", {
              key: "height",
              value: rate * maxWidth + "px",
              level: "props",
            });
          }
        });
      }
    };

    return {
      components,
      defaultTextTemplates,
      currentElement,
      handleChange,
      addItem,
      setActive,
      activePanel,
      page,
      pageChange,
      updatePosition,
      titleChange,
      userInfo,
      saveWork,
      saveIsLoading,
      publish,
      canvasFix,
      isPublishing,
      showPublishForm,
      showpreview,
      preview,
      adjustHeightOnUpload,
    };
  },
});
