
import { defineComponent } from "vue";
import { message } from "ant-design-vue";
import ImageProcesser from "./ImageProcesser.vue";
import { commonUploadCheck, UploadImgProps } from "../helper";
import StyledUploader from "./StyledUploader.vue";

export default defineComponent({
  props: {
    value: {
      type: String,
      required: true,
    },
    ratio: {
      type: Number,
    },
  },
  components: {
    ImageProcesser,
    StyledUploader,
  },
  emits: ["change", "uploaded"],
  setup(props, context) {
    console.log("props", props.value);
    const handleFileUploaded = (uploadedData: any) => {
      message.success("上传成功");
      context.emit("change", uploadedData.resp.url);
      context.emit("uploaded", uploadedData);
    };
    const updateUrl = (value: string) => {
      context.emit("change", value);
    };
    const triggerUploaded = (uploadedData: any) => {
      context.emit("uploaded", uploadedData);
    };
    return {
      handleFileUploaded,
      commonUploadCheck,
      updateUrl,
      triggerUploaded,
    };
  },
});
