
import { defineComponent, computed, ref, watch, nextTick } from "vue";
import StyledUploader from "./StyledUploader.vue";
import { message } from "ant-design-vue";
import {
  UploadOutlined,
  ScissorOutlined,
  LoadingOutlined,
} from "@ant-design/icons-vue";
// @ts-ignore
import Cropper from "cropperjs";
interface CropDataProps {
  x: number;
  y: number;
  width: number;
  height: number;
}
export default defineComponent({
  props: {
    value: {
      type: String,
      required: true,
    },
    showDelete: {
      type: Boolean,
      default: false,
    },
  },
  components: {
    StyledUploader,
    ScissorOutlined,
  },
  emits: ["change", "uploaded"],
  setup(props, context) {
    const backgroundUrl = computed(() => `url(${props.value})`);
    const baseImageUrl = computed(() => props.value.split("?")[0]);
    const dataUrl = ref();
    const showModal = ref(false);
    const cropperImg = ref<null | HTMLImageElement>(null);
    let cropper: Cropper;
    let cropData: CropDataProps | null = null;
    watch(showModal, async (newValue) => {
      if (newValue) {
        await nextTick();
        if (cropperImg.value) {
          cropper = new Cropper(cropperImg.value, {
            crop(event) {
              const { x, y, width, height } = event.detail;

              cropData = {
                x: Math.floor(x),
                y: Math.floor(y),
                width: Math.floor(width),
                height: Math.floor(height),
              };
            },
          });
        }
      } else {
        if (cropper) {
          cropper.destroy();
        }
      }
    });
    const handleOk = () => {
      if (cropData) {
        const { x, y, width, height } = cropData;
        const cropperedUrl =
          baseImageUrl.value +
          `?x-oss-process=image/crop,x_${x},y_${y},w_${width},h_${height}`;
        context.emit("change", cropperedUrl);
        showModal.value = false;
        dataUrl.value = cropper.getCroppedCanvas().toDataURL();
      }
    };
    const handleFileUploaded = (data) => {
      const { resp } = data;

      message.success("上传成功");
      context.emit("change", resp.url);
      context.emit("uploaded", data);
    };
    const handleDelete = () => {
      context.emit("change", "");
    };
    return {
      backgroundUrl,
      showModal,
      baseImageUrl,
      handleFileUploaded,
      cropperImg,
      handleOk,
      dataUrl,
      handleDelete,
    };
  },
});
