
import { defineComponent, computed } from "vue";
import { useStore } from "vuex";
import { map } from "lodash";
import maps from "../propsMap";
import TextareaFix from "./TextareaFix.vue";
import ColorPicker from "./ColorPicker.vue";
import IconSwitch from "./IconSwitch.vue";
import ShadowPicker from "./ShadowPicker.vue";
import ImageProcesser from "./ImageProcesser.vue";
import BackgroundProcesser from "./BackgroundProcesser.vue";
import RenderVnode from "./RenderVNode";
export default defineComponent({
  props: {
    props: {
      type: Object,
      required: true,
    },
    mutationName: {
      type: String,
      default: "updateComponent",
    },
    mutationExtraData: {
      type: Object,
    },
  },
  components: {
    ColorPicker,
    IconSwitch,
    ShadowPicker,
    ImageProcesser,
    TextareaFix,
    BackgroundProcesser,
    RenderVnode,
  },
  emits: ["updated"],
  setup(props, context) {
    const { commit } = useStore();
    const handleCommit = (data: any) => {
      const finalData = props.mutationExtraData
        ? { ...data, ...props.mutationExtraData }
        : data;
      commit(props.mutationName, finalData);
    };
    const finalProps = computed(() => {
      return map(props.props, (value, key) => {
        const {
          component,
          initalTransform,
          afterTransform,
          eventName,
          text,
          valueProp,
          options,
          subComponent,
          extraProps = {},
          parent,
          extraEvent,
        } = maps[key];
        let isHidden = false;
        if (parent) {
          isHidden = !props.props[parent];
        }
        return {
          key,
          component,
          text,
          valueProp,
          isHidden,
          value: initalTransform?.(value),
          extraProps,
          events: {
            [eventName]: (e: any) => {
              handleCommit({ value: afterTransform(e), key });
            },
            ...(extraEvent && {
              [extraEvent]: (data: any) => {
                context.emit("updated", { data, key });
              },
            }),
          },
          options,
          subComponent,
        };
      });
    });
    return {
      maps,
      handleCommit,
      finalProps,
    };
  },
});
