
import { defineComponent, computed, ref } from "vue";
import { useStore } from "vuex";
import {
  RedoOutlined,
  UndoOutlined,
  QuestionOutlined,
} from "@ant-design/icons-vue";
import { GlobalDataProps } from "../store/index";
import { operationText } from "../plugins/hotKeys";
export default defineComponent({
  components: {
    RedoOutlined,
    UndoOutlined,
    QuestionOutlined,
  },
  setup() {
    const modalVisible = ref(false);
    const store = useStore<GlobalDataProps>();
    const histories = computed(() => store.state.editor.histories);
    const historyIndex = computed(() => store.state.editor.historyIndex);
    const undoIsDisabled = computed<boolean>(
      () => store.getters.checkUndoDisable
    );
    const redoIsDisabled = computed<boolean>(
      () => store.getters.checkRedoDisable
    );
    const undoHistory = () => {
      store.commit("undo");
    };
    const redoHistory = () => {
      store.commit("redo");
    };
    return {
      histories,
      undoHistory,
      redoHistory,
      undoIsDisabled,
      redoIsDisabled,
      historyIndex,
      modalVisible,
      operationText,
    };
  },
});
