console.log("shapeList", shapeList);
export default defineComponent({
  components: {
    Uploader,
    FileImageOutlined,
    LoadingOutlined,
    FieldStringOutlined,
    BuildOutlined,
    LText,
    LImage,
    LShape,
  },
  name: "components-list",
  emits: ["on-item-click"],
  setup(props, context) {
    const onItemClick = (data: CreateComponentType) => {
      console.log("data", data);
      if (data.type !== "upload") {
        context.emit("on-item-click", data);
      }
    };
    const handleFileUploaded = (uploadedData: any) => {
      const data = {
        name: "l-image",
        id: uuidv4(),
        props: {
          ...imageDefaultProps,
        },
      } as CreateComponentType;
      message.success("上传成功");
      data.props.imageSrc = uploadedData.resp.url;
      getImageDimensions(uploadedData.resp.url).then((dimension) => {
        const maxWidth = 300;
        data.props.width =
          (dimension.width > maxWidth ? maxWidth : dimension.width) + "px";
        console.log("data", data);
        context.emit("on-item-click", data);
      });
    };
    return {
      textList,
      imageList,
      shapeList,
      onItemClick,
      commonUploadCheck,
      handleFileUploaded,
      generateResetCss,
    };
  },
});
