
import { defineComponent, reactive, ref, Ref, computed, watch } from "vue";
import { useStore } from "vuex";
import { useRouter } from "vue-router";
import { UserOutlined, LockOutlined } from "@ant-design/icons-vue";
import axios, { AxiosRequestConfig } from "axios";
import { message } from "ant-design-vue";
import { GlobalDataProps } from "../store/index";
import { isMobile } from "../helper";

interface RuleFormInstance {
  validate: () => Promise<any>;
}
export default defineComponent({
  components: {
    UserOutlined,
    LockOutlined,
  },
  setup() {
    const store = useStore<GlobalDataProps>();
    const router = useRouter();
    const counter = ref(60);
    let timer: any;
    const form = reactive({
      username: "",
      password: "",
    });
    const publishForm = ref() as Ref<RuleFormInstance>;
    // const status = computed(() => store.state.status);
    const cellnumberValidator = (rule: any, value: string) => {
      const passed = isMobile(value.trim());
      // eslint-disable-next-line prefer-promise-reject-errors
      return passed ? Promise.resolve() : Promise.reject("手机号码格式不正确");
    };
    const startCounter = () => {
      counter.value--;
      timer = setInterval(() => {
        counter.value--;
      }, 1000);
    };
    watch(counter, (newValue) => {
      if (newValue === 0) {
        clearInterval(timer);
        counter.value = 60;
      }
    });
    const codeButtonDisable = computed(() => {
      return !isMobile(form.username.trim()) || counter.value < 60;
    });
    const isLoading = computed(() => store.getters.isLoading);
    const isLoginLoading = computed(() => store.getters.isOpLoading("login"));

    const rules = {
      username: [
        { required: true, message: "手机号码不能为空", trigger: "blur" },
        { validator: cellnumberValidator, trigger: "blur" },
      ],
      password: [
        { required: true, message: "验证码不能为空", trigger: "blur" },
      ],
    };
    const login = () => {
      publishForm.value.validate().then(() => {
        const payload = {
          phoneNumber: form.username,
          veriCode: form.password,
        };
        store.dispatch("loginAndFetch", { data: payload }).then((rawData) => {
          message.success("登录成功 2秒后跳转首页");
          setTimeout(() => {
            router.push("/");
          }, 2000);
        });
      });
    };
    const getCode = () => {
      axios
        .post("/users/genVeriCode", { phoneNumber: form.username }, {
          mutationName: "getCode",
        } as AxiosRequestConfig)
        .then((res) => {
          alert(res.data.data.code);
          message.success("验证码已发送，请注意查收", 5);
          startCounter();
        });
    };
    return {
      form,
      rules,
      publishForm,
      login,
      getCode,
      //   status,
      isMobile,
      counter,
      codeButtonDisable,
      isLoading,
      isLoginLoading,
    };
  },
});
