
import {
  defineComponent,
  PropType,
  computed,
  ref,
  nextTick,
  reactive,
  Ref,
  watch,
} from "vue";
import {
  EditOutlined,
  BarChartOutlined,
  EllipsisOutlined,
  CopyOutlined,
  DeleteOutlined,
  GiftOutlined,
  UserOutlined,
  DownloadOutlined,
} from "@ant-design/icons-vue";
import { Modal } from "ant-design-vue";
import { baseH5URL } from "../main";
import { downloadImage } from "@/helper";
export default defineComponent({
  name: "works-list",
  emits: ["on-copy", "on-delete", "on-static", "on-send"],
  components: {
    EditOutlined,
    BarChartOutlined,
    EllipsisOutlined,
    CopyOutlined,
    DeleteOutlined,
    GiftOutlined,
    UserOutlined,
    DownloadOutlined,
  },
  props: {
    list: {
      type: Array as PropType<any>,
      required: true,
    },
    loading: {
      type: Boolean,
      default: false,
    },
    transferStatus: {
      type: Boolean,
      default: false,
    },
  },
  setup(props, context) {
    const container = ref<null | HTMLElement>(null);
    const sendModal = ref(false);
    const currentItem = ref(0);
    const publishForm = ref() as Ref<any>;
    const listWithBarcode = computed(() => {
      return props.list.map((item) => {
        item.barcodeUrl = `${baseH5URL}/p/${item.id}-${item.uuid}`;
        return item;
      });
    });
    watch(
      () => props.transferStatus,
      () => {
        if (props.transferStatus) {
          sendModal.value = false;
        }
      }
    );
    const form = reactive({
      username: "",
    });
    const rules = {
      username: [
        { required: true, message: "用户昵称不能为空", trigger: "blur" },
      ],
    };
    // const showBarcode = (id: number, url?: string) => {
    //   nextTick(() => {
    //     const container = document.getElementById(`barcode-${id}`);
    //     if (container && url && !container.hasChildNodes()) {
    //       // eslint-disable-next-line no-new
    //       new QRCode(container, {
    //         text: url,
    //         width: 80,
    //         height: 80,
    //       });
    //     }
    //   });
    // };
    const deleteClicked = (id: number) => {
      Modal.confirm({
        title: "确定要删除该作品吗？",
        okText: "删除",
        okType: "danger",
        cancelText: "取消",
        onOk: () => {
          context.emit("on-delete", id);
        },
      });
    };
    const copyClicked = (id: number) => {
      context.emit("on-copy", id);
    };
    const staticClicked = (id: number) => {
      context.emit("on-static", id);
    };
    const saveImage = (url: string) => {
      downloadImage(url);
    };
    const sendClicked = (id: number) => {
      sendModal.value = true;
      currentItem.value = id;
    };
    const sendGift = () => {
      publishForm.value.validate().then(() => {
        context.emit("on-send", {
          id: currentItem.value,
          username: form.username,
        });
      });
    };
    return {
      deleteClicked,
      copyClicked,
      listWithBarcode,
      //   showBarcode,
      container,
      staticClicked,
      sendClicked,
      sendModal,
      publishForm,
      rules,
      form,
      sendGift,
      saveImage,
    };
  },
});
