
import {
  defineComponent,
  reactive,
  ref,
  Ref,
  computed,
  onMounted,
  watch,
  nextTick,
} from "vue";
import { last } from "lodash";
// import ClipboardJS from "clipboard";
import ClipboardJS from "clipboard";
import QRCode from "qrcode";
import { message } from "ant-design-vue";
import { commonUploadCheck } from "../helper";
import { useStore } from "vuex";
import { useRoute } from "vue-router";
import { GlobalDataProps } from "../store";
import { baseH5URL } from "@/main";
interface RuleFormInstance {
  validate: () => Promise<any>;
}
export default defineComponent({
  emits: ["panel-close", "publish-success"],
  setup(props, context) {
    const store = useStore<GlobalDataProps>();
    const route = useRoute();
    const currentWorkId = route.params.id as string;
    const page = computed(() => store.state.editor.page);
    const channels = computed(() => store.state.editor.channels);
    const qrCodeGenerated = ref(false);
    const generateChannelURL = (id?: number) =>
      id
        ? `${baseH5URL}/p/${page.value.id}-${page.value.uuid}?channel=${id}`
        : `${baseH5URL}/p/${page.value.id}-${page.value.uuid}`;
    const generateQRCode = (id?: number) => {
      const ele = document.getElementById(
        id ? `channel-barcode-${id}` : "channel-barcode-template"
      );
      if (ele) {
        // clear the element
        ele.innerHTML = "";
        // eslint-disable-next-line no-new
        // new QRCode(ele, {
        //   text: generateChannelURL(id),
        //   width: 80,
        //   height: 80,
        // });
      }
    };

    onMounted(() => {
      store.dispatch("getChannels", currentWorkId);
      const clipboard = new ClipboardJS(".copy-button");
      clipboard.on("success", (e) => {
        message.success("复制成功", 1);
        e.clearSelection();
      });
      channels.value.forEach((channel) => {
        const ele = document.getElementById(
          `channel-barcode-${channel.id}`
        ) as HTMLCanvasElement;
        QRCode.toCanvas(ele, generateChannelURL(channel.id), {
          width: 100,
        }).then(() => {
          console.log("success");
        });
      });

      setTimeout(() => {
        channels.value.forEach((channel) => {
          generateQRCode(channel.id);
        });
      }, 500);
    });
    watch(
      channels,
      (newChannels, oldChannels) => {
        // creating new channel
        if (
          newChannels.length > oldChannels.length &&
          oldChannels.length !== 0
        ) {
          // grab the last item for new channel
          const createdChannel = last(newChannels);
          if (createdChannel) {
            const id = createdChannel.id;
            const ele = document.getElementById(
              id ? `channel-barcode-${id}` : "channel-barcode-template"
            );
            QRCode.toCanvas(ele, generateChannelURL(id), {
              width: 100,
            }).then(() => {
              console.log("success");
            });
          }
        }
      },
      { deep: true, flush: "post" }
    );
    const tabChange = (activeKey: string) => {
      if (activeKey === "template") {
        nextTick(() => {
          const ele = document.querySelector("#channel-barcode-template");
          console.log("ele", ele);
          QRCode.toCanvas(ele, generateChannelURL(), {
            width: 100,
          }).then(() => {
            console.log("success");
          });
        });
      }
    };

    const form = reactive({
      channelName: "",
    });
    const publishForm = ref() as Ref<RuleFormInstance>;
    const rules = {
      channelName: [
        { required: true, message: "标题不能为空", trigger: "blur" },
      ],
    };
    const updatePage = (key: string, value: string) => {
      store.commit("updatePage", { key, value });
    };
    const deleteDisabled = computed(() => channels.value.length === 1);
    const createChannel = async () => {
      const payload = {
        name: form.channelName,
        workId: parseInt(currentWorkId),
      };
      try {
        await publishForm.value.validate();
        await store.dispatch("createChannel", { data: payload });
        form.channelName = "";
      } catch (e) {
        console.log("e", e);
      }
    };
    const deleteChannel = (id: number) => {
      console.log("id", id);
      store.dispatch("deleteChannel", { urlParams: { id: `${id}` } });
    };
    const publishTemplate = () => {
      store
        .dispatch("publishTemplate", { urlParams: { id: `${currentWorkId}` } })
        .then(() => {
          message.success("模版发布成功", 1);
        });
    };
    const cancelEdit = () => {
      context.emit("panel-close", true);
    };
    return {
      form,
      rules,
      publishForm,
      cancelEdit,
      commonUploadCheck,
      updatePage,
      page,
      createChannel,
      channels,
      generateChannelURL,
      deleteChannel,
      deleteDisabled,
      tabChange,
      publishTemplate,
    };
  },
});
